#!/bin/bash

set -e

ENV="$1"

if [ -z "$ENV" ]; then
    echo "Usage: ./wokwi-build <platformio-environment>"
    exit 1
fi

FIRMWARE=".pio/build/$ENV/firmware.bin"
ELF=".pio/build/$ENV/firmware.elf"

echo "Building PlatformIO environment: $ENV"

pio run -e "$ENV"

if [ ! -f "$FIRMWARE" ] || [ ! -f "$ELF" ]; then
    echo "Build output not found for environment: $ENV"
    exit 1
fi
# pio run -e "$ENV"
# firmware = ".pio/build/$ENV/firmware.bin"
# elf = ".pio/build/$ENV/firmware.elf"

cat > wokwi.toml <<EOF
# Generated by wokwi-build.
# PlatformIO environment: $ENV

[wokwi]
version = 1
firmware = "$FIRMWARE"
elf = "$ELF"
EOF

echo
echo "Wokwi ready: $ENV"